"""Printed 253–255: ellipse elements, derivation and standard orientations."""
import math
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_native_geometry import geometry,path
def ellipse_graph(n):
 vertical=n==16;cx=245;cy=175;a=145;b=85;c=math.sqrt(a*a-b*b)
 def pt(x,y):return(cx+x,cy-y)
 coords=[pt((b if vertical else a)*math.cos(t*math.pi/90),(a if vertical else b)*math.sin(t*math.pi/90)) for t in range(181)]
 paths=[path(coords),path([(45,cy),(445,cy)]),path([(cx,15),(cx,335)])]
 foci=[(0,-c),(0,c)] if vertical else [(-c,0),(c,0)]
 dots=[(0,0)]+foci
 if n==12:
  labels=[(cx+6,cy+22,'Center'),(80,cy-12,'Vertex'),(365,cy-12,'Vertex'),(cx+5,75,'Co-vertex'),(cx+5,275,'Co-vertex'),(cx+12,105,'Minor axis'),(cx-70,cy+43,'Major axis')]
  for x,y in foci:xx,yy=pt(x,y);labels.append((xx-20,yy-12,'Focus'))
 else:
  labels=[(cx+8,cy+22,'C(0,0)')]
  for idx,(x,y) in enumerate(foci):xx,yy=pt(x,y);labels.append((xx+8,yy-10,('F₁(0,c)' if idx else 'F₂(0,−c)') if vertical else ('F₂(c,0)' if idx else 'F₁(−c,0)')))
  for x,y,label in ([(0,a,'V(0,a)'),(0,-a,'V(0,−a)'),(-b,0,'(−b,0)'),(b,0,'(b,0)')] if vertical else [(-a,0,'V(−a,0)'),(a,0,'V(a,0)'),(0,b,'B(0,b)'),(0,-b,'B(0,−b)')]):xx,yy=pt(x,y);labels.append((xx-27,yy-10 if y>=0 else yy+23,label));dots.append((x,y))
 if n==13:
  q=(a*math.cos(.9),b*math.sin(.9));paths.extend([path([pt(*f),pt(*q)]) for f in foci]);xx,yy=pt(*q);labels.append((xx+4,yy-12,'P(x,y)'));dots.append(q)
 labels.extend([(450,cy+5,'x'),(cx-3,12,'y')])
 return geometry('Figure 9.'+str(n),'Figure 9.'+str(n)+' — ellipse centre, foci, vertices and co-vertices'+(' with two focal distances' if n==13 else ''),paths,labels,points=[{'x':pt(x,y)[0],'y':pt(x,y)[1]} for x,y in dots],size=(520,375))
def eccentricity_graph():
 paths=[path([(55,185),(465,185)]),path([(260,35),(260,335)])];labels=[(468,189,'x'),(260,27,'y')]
 for i,e in enumerate([.02,.30,.60,.92,.98]):
  a=145;b=a*math.sqrt(1-e*e);paths.append(path([(260+a*math.cos(t*math.pi/90),185-b*math.sin(t*math.pi/90)) for t in range(181)]));labels.append((375,50+26*i,'e='+str(e)))
 return geometry('Figure 9.14','Figure 9.14 — ellipses with fixed major axis and eccentricities 0.02, 0.30, 0.60, 0.92 and 0.98',paths,labels,size=(520,365))
PAGES=[page('131_page_1.jpg',253,[heading('9.2 Ellipse'),paragraph('In shape and in format, the ellipse is different from the parabola. Although the parabola is open at one end, the ellipse is entirely closed. The parabola has one focus and one vertex, while the ellipse has two foci (plural of focus) and two vertices.'),heading('(i) Ellipse and its elements'),heading('Ellipse'),paragraph('The second type of conic is called an ellipse, and is defined as follows. An ellipse is the set of all points in a plane, the sum of whose distances from two distinct fixed points (foci) is constant.'),ellipse_graph(12),paragraph('Center — It is the point where major and minor axis intersect each other. The midpoint of the connecting two foci line segment is the center.'),paragraph('Focus — There are two focal points on the major axis which define the ellipse. These are at the same distance to both sides from the center.'),paragraph('Major Axis — It is the lengthiest diameter of the ellipse. It has the endpoints on the widest part of the ellipse and passes through the center.'),paragraph('Minor Axis — It is the shortest diameter of the ellipse. It is the perpendicular bisector of the major axis. It has the endpoints on the narrow part of the ellipse and passes through the center.'),paragraph('Vertices — The four points where the major and minor axis touches the ellipse are the vertices. The endpoints of major axis are generally called Vertex and the endpoints of minor axis are generally called Co-vertex.'),paragraph('Chord — It is a line segment that has both the endpoints on the ellipse. Major axis is also the chord which is the longest one in an ellipse.'),heading('Eccentricity of an Ellipse'),paragraph('Eccentricity is the factor related to conic sections which shows how circular the conic section is. More eccentricity means less spherical and less eccentricity means more spherical. It is denoted by e. The eccentricity of an ellipse is showed by the ratio of the distance between the two foci, to the size of the major axis:'),eq(r'e=\frac c a'),paragraph('where e is eccentricity, c is the distance from the center to any one focus and a is the semimajor axis. The eccentricity of an ellipse is between 0 and 1 (0<e<1). If eccentricity is zero the foci match with the center point and become a circle. If eccentricity moves toward 1, the ellipse gets a more stretched shape.'),note('For distinct foci separated by 2c, the constant distance sum must be 2a>2c for a nondegenerate ellipse. At equality the locus is the joining segment; if smaller, it is empty. A circle is the coincident-focus limit e=0. The shape is planar and circular, rather than spherical. The major-axis endpoints are vertices and the minor-axis endpoints are co-vertices; all four are extreme axis intersections, not tangencies of the axes.')]),
page('131_page_2.jpg',254,[heading('Directrix of an ellipse'),paragraph('Directrix is the line which is parallel to the minor axis of the ellipse and related to both the foci of the ellipse.'),heading('Latus rectum of an Ellipse'),paragraph('It is the line parallel to directrix and passes through any of the focus of an ellipse. It is denoted by 2l. In an ellipse, latus rectum is 2b²/a (where a is one half of the major diameter and b is one half of the minor diameter). The half of latus rectum till its intersection point with the major axis is the semi latus rectum. It is denoted by l.'),heading('Note: General form of the ellipse'),paragraph('If P(x,y) is any point on the ellipse, the distances from the two foci F₁(−c,0) and F₂(c,0) to P(x,y) are:'),eq(r'd(F_1,P)=(x+c,y-0)'),eq(r'|d(F_1,P)|=\sqrt{(x+c)^2+y^2}'),eq(r'd(F_2,P)=(x-c,y-0)'),eq(r'|d(F_2,P)|=\sqrt{(x-c)^2+y^2}'),ellipse_graph(13),paragraph('By definition of an ellipse, the general form of an ellipse is:'),eq(r'|d(F_1,P)|+|d(F_2,P)|=2a','32'),eq(r'\sqrt{(x+c)^2+y^2}+\sqrt{(x-c)^2+y^2}=2a'),eq(r'\sqrt{(x+c)^2+y^2}=2a-\sqrt{(x-c)^2+y^2}'),paragraph('Squaring both sides to obtain:'),eq(r'(x+c)^2+y^2=4a^2-4a\sqrt{(x-c)^2+y^2}+(x-c)^2+y^2'),eq(r'4a\sqrt{(x-c)^2+y^2}=4a^2-4cx'),eq(r'a\sqrt{(x-c)^2+y^2}=a^2-cx','33'),paragraph('Again squaring to obtain:'),eq(r'a^2[(x-c)^2+y^2]=a^4-2a^2cx+c^2x^2'),eq(r'a^2(x^2-2cx+c^2+y^2)=a^4-2a^2cx+c^2x^2'),eq(r'a^2x^2-2a^2cx+a^2c^2+a^2y^2=a^4-2a^2cx+c^2x^2'),eq(r'a^2x^2-c^2x^2+a^2y^2=a^4-a^2c^2'),eq(r'(a^2-c^2)x^2+a^2y^2=a^2(a^2-c^2)'),eq(r'b^2x^2+a^2y^2=a^2b^2,\quad b^2=a^2-c^2,\quad a>0,\ b>0'),eq(r'\frac{x^2}{a^2}+\frac{y^2}{b^2}=1','34'),paragraph('Divide out by a²b².'),note('The source labels coordinate displacement vectors as d(Fᵢ,P); their magnitudes are the scalar distances. A noncircular ellipse has two directrices, paired with its foci: x=±a/e=±a²/c in this horizontal orientation. The latus rectum is a finite chord through a focus, of length 2b²/a, rather than the whole line. Assume a>c>0 and b²=a²−c²>0. Conversely the standard equation gives |x|≤a and focal distances a+cx/a and a−cx/a, both positive; their sum is 2a, so the two squarings introduce no extraneous points.')]),
page('132_page_1.jpg',255,[heading('(ii) Circle is a special case of an ellipse'),paragraph('The relative shape of an ellipse can be determined by its eccentricity e. The distance from the center of the ellipse to a focus is c, and the distance from the center to a vertex is a. The eccentricity is given by:'),eq(r'e=\frac{\mathrm{distance\ from\ center\ to\ focus}}{\mathrm{distance\ from\ center\ to\ vertex}}=\frac c a','35'),paragraph('The eccentricity of all ellipses is in a range between 0 and 1 (0<e<1). This is shown in Figure 9.14. An ellipse with eccentricity close to 1 is long and thin, and the foci are relatively far apart. If eccentricity is small, close to 0, then the ellipse resembles a circle. It can be shown that the circle is a special case of the ellipse when e=0.'),eccentricity_graph(),heading('(iii) Standard form of equation of an ellipse'),paragraph('The standard form of the ellipse with center at the origin, length of the semimajor axis a, length of the semiminor axis b and major axis along the x-axis is shown in Figure 9.15:'),eq(r'\frac{x^2}{a^2}+\frac{y^2}{b^2}=1','36'),paragraph('If we replace the foci on the y-axis, center at the origin and pick any point P(x,y) on the plane, we develop the equation of the vertical ellipse. The standard form with center at the origin, semimajor axis a, semiminor axis b and major axis along the y-axis is shown in Figure 9.16:'),eq(r'\frac{x^2}{b^2}+\frac{y^2}{a^2}=1','37'),ellipse_graph(15),ellipse_graph(16),heading('Graphing Ellipse'),paragraph('In order to sketch an ellipse, plot the center, the intercepts ±a on the major axis and ±b on the minor axis. First rewrite the equation in standard form, so there is a 1 on the right and the numerator coefficients of the square terms are 1. The center is at (0,0). For x-intercepts plot the square root of a²; for y-intercepts plot the square root of b², then draw the ellipse using these intercepts. The longer axis is called major axis. If this axis is horizontal, the ellipse is horizontal; if vertical, the ellipse is vertical. The orientation with center C(0,0), vertices/endpoints of major axis and endpoints of semiminor axis are summarized in the box:'),note('The intercept instruction a along x and b along y applies to horizontal equation (36); in vertical equation (37), x-intercepts are ±b and y-intercepts ±a. For fixed a, b=a√(1−e²), explaining Figure 9.14. Ellipses with distinct foci have 0<e<1; allowing the circle gives 0≤e<1. Both orientations have c²=a²−b² with a≥b>0.')])]
